package local.station.controller;

import android.content.Context;
import android.content.SharedPreferences;
import android.os.Build;
import org.json.*;
import javax.net.ssl.HttpsURLConnection;
import java.io.*;
import java.net.URL;
import java.security.SecureRandom;
import java.util.*;

/** Opt-in, schema-only reporting. No raw logs or personal identifiers leave the app. */
final class DiagnosticSharing {
 interface Reply{void send(String type,Object value);}
 private static final String ORIGIN="https://station-studio-community.shaaaape.chatgpt.site/api/diagnostics/",POLICY="2026-11-07.1";
 private static final Set<String> CODES=new HashSet<>(Arrays.asList("CHECK_START","DISCOVERY","DISCOVERY_DONE","ADB_CONNECT","ADB_READY","ADB_AUTH_REQUIRED","PORT_CLOSED","NETWORK_TIMEOUT","NETWORK_DENIED","NO_LOCAL_NETWORK","ADB_NO_REPLY","NOT_ADB","ADB_PROTOCOL","ADB_SHELL_ERROR","SHELL_EXIT","ROOT_RESULT","PANEL_UNAVAILABLE","PANEL_READY","ROOT_QUEUE_READY","ROOT_QUEUE_REJECTED","ROOT_QUEUE_TIMEOUT","KEY_HANDOFF","CANCELLED","PHASE_NETWORK","PHASE_ADB","PHASE_ROOT","PHASE_PANEL","APP_OPEN","LOCAL_WEB_ERROR","ROOT_NETWORK","ROOT_START","ROOT_INSTALL_OK","ROOT_INSTALL_FAILED","SETUP_ERROR","ROOT_OPERATION_PENDING","ROOT_OPERATION_LOCKED","ROOT_SERVICE_EXISTS","ROOT_PROCESS_ACTIVE","ROOT_FILE_MISSING","ROOT_PROFILE_UNSUPPORTED","ROOT_UPTIME_WAIT","ROOT_BOOT_CHANGED","ROOT_DNS_MISSING","ROOT_GATEWAY_MISSING"));
 private final Context context;private final SetupJournal journal;private final Reply reply;private final SharedPreferences preferences;private static final Object lock=new Object();
 DiagnosticSharing(Context c,SetupJournal j,Reply r){context=c;journal=j;reply=r;preferences=c.getSharedPreferences("diagnostics-consent",0);}
 void revokeLocal(){preferences.edit().putBoolean("automatic",false).remove("version").commit();}
 private JSONObject call(String path,String method,JSONObject body,String authorization)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(ORIGIN+path).openConnection(java.net.Proxy.NO_PROXY);c.setConnectTimeout(7000);c.setReadTimeout(9000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("User-Agent","AliceKit-Diagnostics/2.9.3");if(authorization!=null)c.setRequestProperty("Authorization",authorization);try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=code<400?c.getInputStream():c.getErrorStream()){if(in==null)throw new IOException();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>32768)throw new IOException();}}JSONObject j=new JSONObject(new String(out.toByteArray(),"UTF-8"));if(code>=400)throw new IOException(j.optString("error","Сервер не подтвердил действие"));return j;}finally{c.disconnect();}}
 private JSONArray receipts()throws Exception{String value=new SecureStore(context).loadPrivate("diagnostic-receipts");JSONArray rows=value==null?new JSONArray():new JSONArray(value),live=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.has("expires")||row.optLong("expires")+2L*86400000>System.currentTimeMillis())live.put(row);}return live;}
 private void save(JSONArray rows)throws Exception{new SecureStore(context).savePrivate("diagnostic-receipts",rows.toString());}
 private String random(int size){byte[] b=new byte[size];new SecureRandom().nextBytes(b);StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 JSONObject preview()throws Exception{JSONArray all=journal.entries(),events=new JSONArray();long start=0;String[] reasons={"ROOT_OPERATION_PENDING","ROOT_OPERATION_LOCKED","ROOT_SERVICE_EXISTS","ROOT_PROCESS_ACTIVE","ROOT_FILE_MISSING","ROOT_PROFILE_UNSUPPORTED","ROOT_UPTIME_WAIT","ROOT_BOOT_CHANGED","ROOT_DNS_MISSING","ROOT_GATEWAY_MISSING"};for(int i=Math.max(0,all.length()-60);i<all.length();i++){JSONObject e=all.getJSONObject(i);String code=e.optString("code");if(!e.optString("app").equals("2.9.3"))continue;if(code.equals("ROOT_INSTALL_FAILED"))for(String reason:reasons)if(e.optString("detail").contains(reason)){code=reason;break;}if(CODES.contains(code)){if(start==0)start=e.optLong("time");events.put(new JSONObject().put("code",code).put("offsetMs",Math.max(0,Math.min(86400000,e.optLong("time")-start))));}}return new JSONObject().put("app","2.9.3").put("sdk",Build.VERSION.SDK_INT).put("model","unknown").put("events",events);}

 void action(String action){new Thread(()->{try{synchronized(lock){if(action.equals("revoke")){preferences.edit().putBoolean("automatic",false).remove("version").commit();reply.send("diagnosticMessage","Автоматическая отправка выключена. Для удаления прежних отчётов нажмите отдельную кнопку удаления.");}else if(action.equals("delete")){preferences.edit().putBoolean("automatic",false).remove("version").commit();JSONArray old=receipts(),remaining=new JSONArray();for(int i=0;i<old.length();i++){JSONObject row=old.getJSONObject(i);try{call("report","DELETE",null,"Report "+row.getString("id")+"."+row.getString("secret"));}catch(Exception e){remaining.put(row);}}save(remaining);reply.send("diagnosticMessage",remaining.length()==0?"Удаление подтверждено. Автоматическая отправка выключена.":"Часть удалений не подтверждена. Квитанции сохранены; повторите удаление позже.");}else if(action.equals("once")||action.equals("automatic")){send(action.equals("automatic"));}JSONObject config=call("config","GET",null,null);config.put("automatic",preferences.getBoolean("automatic",false)&&POLICY.equals(preferences.getString("version","")));config.put("preview",preview());config.put("receipts",receipts().length());reply.send("diagnosticState",config);}}catch(Exception e){reply.send("diagnosticMessage",SetupJournal.safe(e.getMessage()==null?"Сервер недоступен. Локальный журнал сохранён.":e.getMessage()));}},"alicekit-diagnostics").start();}
 private void send(boolean automatic)throws Exception{JSONObject config=call("config","GET",null,null);if(!config.optBoolean("enabled")||!POLICY.equals(config.optString("policyVersion")))throw new IOException(config.optString("reason","Отправка выключена или требуется новая версия согласия"));JSONObject report=preview();if(report.getJSONArray("events").length()==0)throw new IOException("Пока нет событий подключения для отчёта");JSONArray stored=receipts();if(stored.length()>=160)throw new IOException("Сначала удалите прежние отчёты; квитанции не теряются автоматически");String id=random(16),secret=random(32);stored.put(new JSONObject().put("id",id).put("secret",secret).put("expires",System.currentTimeMillis()+30L*86400000));save(stored);report.put("id",id).put("deleteSecret",secret).put("consent",new JSONObject().put("version",POLICY).put("granted",true).put("mode",automatic?"automatic":"once"));if(automatic)preferences.edit().putBoolean("automatic",true).putString("version",POLICY).commit();call("report","POST",report,null);preferences.edit().putLong("lastSent",System.currentTimeMillis()).commit();reply.send("diagnosticMessage","Технический отчёт отправлен. Квитанция удаления сохранена только на вашем телефоне.");}
 void automatic(){if(!preferences.getBoolean("automatic",false)||!POLICY.equals(preferences.getString("version",""))||System.currentTimeMillis()-preferences.getLong("lastSent",0)<21600000||System.currentTimeMillis()-preferences.getLong("lastAttempt",0)<120000)return;new Thread(()->{synchronized(lock){try{preferences.edit().putLong("lastAttempt",System.currentTimeMillis()).commit();if(preferences.getBoolean("automatic",false)&&POLICY.equals(preferences.getString("version","")))send(true);}catch(Exception ignored){/* No retry loop and no loss of the local journal. */}}},"alicekit-diagnostic-auto").start();}
}
